class Solution {
public:
    // 算法思路: 单调栈。栈中存下标且高度递增, 遇到更矮的柱子时弹出并计算矩形面积。
    // 关键点: 末尾追加 0 哨兵保证所有柱子出栈; 弹出后新栈顶即左侧边界。
    // 时间复杂度 O(n), 空间复杂度 O(n)。
    int largestRectangleArea(vector<int>& heights) {
        vector<int> h = heights;
        h.push_back(0);                // 末尾哨兵
        stack<int> st;
        st.push(-1);
        long long ans = 0;
        for (int i = 0; i < (int)h.size(); i++) {
            while (st.top() != -1 && h[st.top()] > h[i]) {
                int idx = st.top(); st.pop();
                ans = max(ans, (long long)h[idx] * (i - st.top() - 1));
            }
            st.push(i);
        }
        return (int)ans;
    }
};

